#!/usr/bin/env python3
from pathlib import Path
import re
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'dist')
paths = [
    root / 'berry-harvesting.html',
    root / 'en' / 'berry-harvesting.html',
    root / 'cz' / 'berry-harvesting.html',
]

gentle_re = re.compile(r'<section class="section soft gentle-crops">.*?</section>', re.S)
models_re = re.compile(r'<section class="section dark" id="models">.*?</section>', re.S)

BLUEBERRY = ''

RASPBERRY = ''

CURRANT = ''

layout_css = f'''
.gentle-crops{{position:relative;overflow:hidden;padding:72px 0 86px!important;background-color:#f2f5f5!important;background-image:url("data:image/webp;base64,{{BLUEBERRY}}"),url("data:image/webp;base64,{{RASPBERRY}}"),url("data:image/webp;base64,{{CURRANT}}");background-repeat:no-repeat;background-position:right 3% top 80px,left -24px bottom -6px,right 1% bottom -8px;background-size:170px auto,220px auto,185px auto}}
.gentle-crops>.wrap{{display:flex;flex-direction:column;position:relative;z-index:1}}
.gentle-crops>.wrap>.eyebrow{{order:1}}
.gentle-crops>.wrap>h2{{order:2}}
.gentle-crops>.wrap>.lead{{order:3;max-width:900px}}
.gentle-crops .crop-bridge{{order:4;margin:28px 0 0!important;font:700 clamp(30px,3vw,42px)/1.05 var(--serif)!important;color:var(--navy)!important}}
.gentle-crops .ripeness{{order:5;margin-top:28px!important;position:relative;z-index:2}}
.gentle-crops .ripeness article{{background:rgba(255,255,255,.95)!important;backdrop-filter:blur(3px)}}
.gentle-crops .crop-gallery{{display:none!important}}
@media(max-width:900px){{.gentle-crops{{padding:56px 0 70px!important;background-position:right -28px top 130px,left -60px bottom -4px,right -36px bottom 16px;background-size:115px auto,145px auto,120px auto}}.gentle-crops .crop-bridge{{font-size:30px!important}}}}
'''

for p in paths:
    if not p.exists():
        raise SystemExit(f'Missing berry page: {p}')
    s = p.read_text(encoding='utf-8')
    gentle = gentle_re.search(s)
    models = models_re.search(s)
    if not gentle:
        raise SystemExit(f'Gentle crop module not found in {p}')
    if not models:
        raise SystemExit(f'Models module not found in {p}')

    models_html = models.group(0)
    s = s[:models.start()] + s[models.end():]
    gentle = gentle_re.search(s)
    insert_at = gentle.end()
    s = s[:insert_at] + models_html + s[insert_at:]

    if 'background-image:url("data:image/webp;base64,' not in s:
        s = s.replace('</style>', layout_css + '</style>', 1)

    if s.find('gentle-crops') > s.find('id="models"'):
        raise SystemExit(f'Models section order validation failed in {p}')
    p.write_text(s, encoding='utf-8')
    print(f'Moved models section and applied floating berry layout: {p}')
